 1	// Latin-1 Supplement
 2	// upper case ranges
 3	// [À-ÖØ-ß]
 4	// lower case ranges
 5	// [à-öø-ÿ]
 6	export const magicSplit = /^[a-zà-öø-ÿа-я]+|[A-ZÀ-ÖØ-ßА-Я][a-zà-öø-ÿа-я]+|[a-zà-öø-ÿа-я]+|[0-9]+|[A-ZÀ-ÖØ-ßА-Я]+(?![a-zà-öø-ÿа-я])/g;
 7	export const spaceSplit = /\S+/g;
 8	/**
 9	 * A string.matchAll function that will return an array of "string parts" and the indexes at which
10	 * it split each part
11	 */
12	export function getPartsAndIndexes(string, splitRegex) {
13	    const result = { parts: [], prefixes: [] };
14	    const matches = string.matchAll(splitRegex);
15	    let lastWordEndIndex = 0;
16	    for (const match of matches) {
17	        if (typeof match.index !== 'number')
18	            continue;
19	        const word = match[0];
20	        result.parts.push(word);
21	        const prefix = string.slice(lastWordEndIndex, match.index).trim();
22	        result.prefixes.push(prefix);
23	        lastWordEndIndex = match.index + word.length;
24	    }
25	    const tail = string.slice(lastWordEndIndex).trim();
26	    if (tail) {
27	        result.parts.push('');
28	        result.prefixes.push(tail);
29	    }
30	    return result;
31	}
32	/**
33	 * A function that splits a string on words and returns an array of words.
34	 *
35	 * - It can prefix each word with a given character
36	 * - It can strip or keep special characters, this affects the logic for adding a prefix as well
37	 */
38	export function splitAndPrefix(string, options) {
39	    const { keepSpecialCharacters = false, keep, prefix = '' } = options || {};
40	    const normalString = string.trim().normalize('NFC');
41	    const hasSpaces = normalString.includes(' ');
42	    const split = hasSpaces ? spaceSplit : magicSplit;
43	    const partsAndIndexes = getPartsAndIndexes(normalString, split);
44	    return partsAndIndexes.parts
45	        .map((_part, i) => {
46	        let foundPrefix = partsAndIndexes.prefixes[i] || '';
47	        let part = _part;
48	        if (keepSpecialCharacters === false) {
49	            if (keep) {
50	                part = part
51	                    .normalize('NFD')
52	                    .replace(new RegExp(`[^a-zA-ZØßø0-9${keep.join('')}]`, 'g'), '');
53	            }
54	            if (!keep) {
55	                part = part.normalize('NFD').replace(/[^a-zA-ZØßø0-9]/g, '');
56	                foundPrefix = '';
57	            }
58	        }
59	        if (keep && foundPrefix) {
60	            foundPrefix = foundPrefix.replace(new RegExp(`[^${keep.join('')}]`, 'g'), '');
61	        }
62	        // the first word doesn't need a prefix, so only return the found prefix
63	        if (i === 0) {
64	            // console.log(`foundPrefix → `, foundPrefix)
65	            return foundPrefix + part;
66	        }
67	        if (!foundPrefix && !part)
68	            return '';
69	        if (!hasSpaces) {
70	            // return the found prefix OR fall back to a given prefix
71	            return (foundPrefix || prefix) + part;
72	        }
73	        // space based sentence was split on spaces, so only return found prefixes
74	        if (!foundPrefix && prefix.match(/\s/)) {
75	            // in this case we have no more found prefix, it was trimmed, but we're looking to add a space
76	            // so let's return that space
77	            return ' ' + part;
78	        }
79	        return (foundPrefix || prefix) + part;
80	    })
81	        .filter(Boolean);
82	}
83	/**
84	 * Capitalises a single word
85	 *
86	 * @returns The word with the first character in uppercase and the rest in lowercase
87	 */
88	export function capitaliseWord(string) {
89	    const match = string.matchAll(magicSplit).next().value;
90	    const firstLetterIndex = match ? match.index : 0;
91	    return (string.slice(0, firstLetterIndex + 1).toUpperCase() +
92	        string.slice(firstLetterIndex + 1).toLowerCase());
93	}

